eral:"General",tabTemplates:"Paths & templates",tabMaintenance:"Maintenance",tabAbout:"About",languageName:"Language",languageDesc:"Display language for the settings panel and commands.",langAuto:"Auto (follow Obsidian)",langZh:"\u4E2D\u6587",langEn:"English",languageChangeHint:"Command names update after the plugin is reloaded.",autoNumberName:"Global auto-numbering",autoNumberDesc:'Number headings as you edit; when off, use "Renumber now" instead.',debounceName:"Debounce delay",debounceDesc:(i,n,e)=>`How long after you stop typing to renumber (${i}\u2013${n} ms, default ${e}).`,resetTooltip:i=>`Reset to default ${i} ms`,updateBacklinksName:"Sync internal links (backlinks)",updateBacklinksDesc:"When a heading's text changes, update links to it in other notes.",headingLinkSuggestName:"Heading link suggestions",headingLinkSuggestDesc:"Suggest matching headings as you type; pick one to insert a link.",headingSuggestThisFile:"(this file)",noticeHeadingIndexTruncated:i=>`Vault too large: heading index built partially (${i} headings indexed); suggestions work within the indexed range.`,vcCoexistName:"When Various Complements is enabled",vcCoexistDesc:"Both plugins share one suggestion popup, so only one can show it.",vcCoexistYield:"Yield to Various Complements (recommended)",vcCoexistOwn:"This plugin wins (hides VC's popup)",vcCoexistFallbackHint:"Dictionary integration is off, so this plugin still serves suggestions.",sectionNumbering:"Auto-numbering",sectionLinking:"Link maintenance",sectionSuggest:"Heading link suggestions",vcModeName:"Various Complements integration",vcModeDesc:"Export the heading index as a VC custom dictionary.",vcModeOff:"Off",vcModeManual:"Manual",vcModeAuto:"Automatic",vcNotInstalledNotice:"Various Complements not detected (not installed or not enabled); automatic configuration cancelled. Install and enable it, or use Manual mode.",vcDictionaryPathLabel:"Dictionary file path",vcCopyPathButton:"Copy path",noticeVcPathCopied:"Dictionary file path copied.",vcManualConfirmTitle:"Enable manual integration",vcManualConfirmBody:`A heading dictionary file will be generated and maintained in this plugin's folder (no VC setting is modified). Copy the path into VC's "Custom dictionary paths" and enable "Custom dictionary complement"; clearing VC's "Displayed text suffix" is recommended, otherwise candidates render as "heading => ...".`,vcManualConfirmButton:"Generate dictionary",vcAutoConfirmTitle:"Enable automatic integration",vcAutoConfirmBody:"A heading dictionary will be generated and VC configured automatically (safety-checked; aborts without touching your VC settings if it can't write safely). Continue?",vcAutoConfirmPoints:["Generate/maintain the heading dictionary (capped at 20,000 headings)",'Write VC settings: dictionary path + "Custom dictionary complement" + trigger threshold of 1 character',`Clear VC's "Displayed text suffix" (global: affects your other custom dictionaries too)`,`Raise VC's "Max number of suggestions" to at least 10 (global; only raised, never lowered)`,"Reload VC dictionaries after writing (failure is reported separately)"],vcDescriptionOffHint:"VC hides the candidate source line (Description on suggestion: None).",vcAutoConfirmButton:"Confirm & configure",noticeVcAutoWriteSuccess:"Various Complements integration configured automatically.",noticeVcAutoWriteInvalidShape:"VC's configuration shape did not match expectations; automatic write aborted (its settings untouched). Use Manual mode or inspect VC's config.",noticeVcAutoWriteNotInstalled:"Could not configure VC automatically (not installed / not enabled / data file missing); install and enable it, or use Manual mode.",noticeVcReloadFailed:`The dictionary and VC settings were written, but reloading VC dictionaries failed; run VC's "Reload custom dictionaries" command (or restart Obsidian).`,noticeVcDictionaryTruncated:i=>`The total number of headings (${i}) exceeds the dictionary cap; the dictionary was truncated and works within the included range.`,pathRulesHeading:"Path rules",pathRulesDesc:'Map paths to templates: folder rules end with "/", the "/" root rule is the global default, and the most specific rule wins.',pathNoRootWarn:'\u26A0 No root path rule (/). With "Global auto-numbering" on, files that match no rule will not be numbered.',addRootRule:"+ Add / root rule",addRule:"Add rule",pathColPattern:"Path pattern",pathColTemplate:"Template",pathEmpty:'(No rules yet; add a "/" root rule to cover the whole vault.)',pathInputPlaceholder:"e.g. Projects/ or Notes/Deep Work.md or /",templateMissingSuffix:i=>`${i} (missing)`,clearInputTooltip:"Clear this path",deleteRuleTooltip:"Delete this rule",dragHandleTooltip:"Drag to reorder",pathDuplicateWarn:i=>`This path is already used by rule #${i}; one path can map to only one template. Edit or delete one of them first.`,pathSuggestEmptyFolder:"(This folder is empty)",pathSuggestBackTooltip:"Go up one level",pathSuggestDescendTooltip:"View contents",pathSuggestSelectHereTooltip:"Select this level",pathTemplateNone:"No numbering",batchRenumberTooltip:"Batch renumber: renumber every file matched by this rule",batchRenumberNoneTooltip:"This rule is set to \u201CNo numbering\u201D \u2014 nothing to renumber",batchModalTitle:"Batch renumber",batchModalBody:(i,n)=>`Renumbers ${n} Markdown file(s) matching \u201C${i}\u201D, each with its own effective template. Files set to \u201CNo numbering\u201D, disabled via frontmatter, or holding unclaimed foreign numbering are skipped; open files support undo, closed files are rewritten directly.`,batchModalConfirm:"Renumber",batchModalCancel:"Cancel",pathColMode:"Mode",pathModeWrite:"Write to file",pathModeVirtual:"Display only",pathModeTooltip:"Write to file: numbers are written into the note and show up in external editors, GitHub and Publish. Display only: numbers are shown inside Obsidian and the note is never changed.",batchRenumberVirtualTooltip:"This rule is display-only \u2014 numbers are never written, nothing to renumber",modeModalTitle:"Numbering mode change",modeModalLeaving:(i,n,e)=>`${i} file(s) contain numbers written by this plugin, and the plugin will stop writing to them (${n} switch to display-only, ${e} to no numbering).`,modeModalClearLabel:"Remove the numbers this plugin wrote in these files (hand-written numbers are left alone). If unchecked, the numbers stay; display-only files will flag them as leftovers.",modeModalEntering:i=>`${i} file(s) will switch from display-only to write-to-file.`,modeModalWriteLabel:"Write numbers into these files now (otherwise on the next edit; open files update right away)",modeModalConfirm:"Confirm",noticeModeCleared:i=>`Removed plugin-written numbers from ${i} file(s)`,templatesHeading:"Templates",templatesDesc:"Define the numbering format and whitelist per heading level; which file uses which template is decided by the Path rules above.",addTemplate:"New template",deleteBtn:"Delete",topLevelName:"Start level",bottomLevelName:"End level",ancestorSelf:"Own style (1.a.\u2460)",ancestorArabic:"All Arabic (\u4E00 / 1.1)",colLevel:"Level",colPrefix:"Prefix",colNumeral:"Numeral",colNumberSep:"Number sep.",colSuffix:"Suffix",colTitleSep:"Title sep.",colPreview:"Preview",inheritDepthAll:"All",previewHeadingWord:"Heading",skipFillFill:"Fill",skipFillDrop:"Drop (omit the segment)",skipFillNone:"Don't number (leave as-is)",numeralArabic:"1, 2, 3",numeralCjk:"\u4E00, \u4E8C, \u4E09",numeralCircled:"\u2460, \u2461, \u2462",numeralLowerAlpha:"a, b, c",numeralUpperAlpha:"A, B, C",numeralLowerRoman:"i, ii, iii",numeralUpperRoman:"I, II, III",matchExact:"Exact",matchPartial:"Partial",matchSubtree:"Subtree",wlInputPlaceholder:"Type a word and press Enter to add\u2026",wlFilterPlaceholder:"Filter entries\u2026",wlSortAdded:"By added order",wlSortAz:"A\u2013Z",wlSortMatch:"By match type",wlFilterNoMatch:"(No entries match the filter)",wlEmpty:"No entries yet \u2014 type a word above and press Enter; matched headings stay unnumbered.",wlEdi